class Leksak:
    def __init__(self, färg, åldersgräns):
        self.färg = färg
        self.åldersgräns = åldersgräns

    def __str__(self):
        return "En leksak för barn över "+ str(self.åldersgräns)+" år med färgen "+self.färg+"."

class Hopprep(Leksak):
    def __init__(self, färg, åldersgräns, längd):
        self.färg = färg
        self.åldersgräns = åldersgräns
        self.längd = längd

    def __str__(self):
        return "Det här är ett hopprep som är "+ str(self.längd) + "cm långt."

r = Hopprep("blå", 3, 150)
l = Leksak("grön", 8)

print(r, l)

class Bil(Leksak):
    def __init__(self, färg, åldersgräns, ljudnivå):
        self.ljudnivå = ljudnivå
        super().__init__(färg, åldersgräns)

b = Bil("röd", 5, 45)
print(b)
